function decodeFile(buf) {
  let text, enc = 'utf8';
  if (buf[0] === 0xFF && buf[1] === 0xFE) { text = buf.slice(2).toString('utf16le'); enc = 'utf16le'; }
  else if (buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF) { text = buf.slice(3).toString('utf8'); enc = 'utf8bom'; }
  else { text = buf.toString('utf8'); }
  const first = text.split('\n')[0];
  const delim = (first.split('\t').length > first.split(',').length) ? '\t' : ',';
  return { text: text, enc: enc, delim: delim };
}
function parseCsv(text, delim) {
  const rows = []; let row = []; let cell = ''; let q = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (q) {
      if (ch === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else { q = false; } }
      else { cell += ch; }
    } else if (ch === '"' && cell === '') { q = true; }
    else if (ch === delim) { row.push(cell); cell = ''; }
    else if (ch === '\n') { row.push(cell.replace(/\r$/, '')); rows.push(row); row = []; cell = ''; }
    else { cell += ch; }
  }
  if (cell !== '' || row.length) { row.push(cell.replace(/\r$/, '')); rows.push(row); }
  while (rows.length && rows[rows.length - 1].every(function (c) { return c === ''; })) { rows.pop(); }
  return rows;
}
function writeCsv(rows, delim, enc) {
  const lines = rows.map(function (r) {
    return r.map(function (c) {
      c = String(c == null ? '' : c);
      return (c.indexOf(delim) >= 0 || c.indexOf('"') >= 0 || c.indexOf('\n') >= 0) ? '"' + c.split('"').join('""') + '"' : c;
    }).join(delim);
  });
  const text = lines.join('\r\n') + '\r\n';
  if (enc === 'utf16le') { return Buffer.concat([Buffer.from([0xFF, 0xFE]), Buffer.from(text, 'utf16le')]); }
  if (enc === 'utf8bom') { return Buffer.concat([Buffer.from([0xEF, 0xBB, 0xBF]), Buffer.from(text, 'utf8')]); }
  return Buffer.from(text, 'utf8');
}
// Apply the approved changes to the original English file
const sub = $('Read Submission').first().json;
const decisions = $('Extract Reviewed Workbook').all().map(function (i) { return i.json; });
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const d = decodeFile(buf);
const rows = parseCsv(d.text, d.delim);
const head = rows[0].map(function (h) { return String(h).trim(); });
const applied = [], rejected = [], notes = [], skipped = [], undecided = [];
for (const r of decisions) {
  if (!r['ID']) continue;
  const dec = String(r['Apply/Reject'] || '').trim().toLowerCase();
  const own = String(r['Your own fix (optional)'] || '').trim();
  const fix = own || String(r['Suggested fix'] || '');
  const label = '#' + r['ID'] + ' row ' + r['Row'] + ' ' + r['Column'] + ': ' + String(r['Current text']).slice(0, 80);
  if (dec.indexOf('rej') === 0) { rejected.push(label + (r['Reason (only if Reject)'] ? ' (reason: ' + r['Reason (only if Reject)'] + ')' : '')); continue; }
  if (dec.indexOf('app') !== 0) { undecided.push(label); continue; }
  if (r['Type'] !== 'Change in file') { notes.push(r['Problem'] + (fix ? ' -> ' + fix : '') + ' [row ' + r['Row'] + ': ' + String(r['Current text']).slice(0, 80) + ']'); continue; }
  const ci = head.indexOf(String(r['Column']));
  const ri = Number(r['Row']) - 1;
  if (ci < 0 || !rows[ri] || !fix) { skipped.push(label + ' (no single cell or no fix: fix it in the file yourself)'); continue; }
  if (String(rows[ri][ci]) !== String(r['Current text'])) { skipped.push(label + ' (cell text changed since the scan)'); continue; }
  rows[ri][ci] = fix; applied.push(label + ' -> ' + fix);
}
const out = writeCsv(rows, d.delim, d.enc);
const base = 'EN_corrected_' + sub.product.replace(/[^A-Za-z0-9]+/g, '_') + '.csv';
const en = await this.helpers.prepareBinaryData(out, base, 'text/csv');
const review = $('Download Reviewed Workbook').first().binary.data;
return [{ json: { applied: applied, rejected: rejected, notes: notes, skipped: skipped, undecided: undecided, en_name: base }, binary: { en: en, review: review } }];

